package app.kinnect.live;
import android.app.*;import android.os.*;import android.widget.*;import android.view.*;
/** Reports bytes written separately from the server's final response. */
final class UploadProgress implements NativeApi.Progress {
 private final Activity activity;private final Handler ui=new Handler(Looper.getMainLooper());private AlertDialog dialog;private TextView label;private ProgressBar bar;private boolean closed;private View.OnAttachStateChangeListener lifecycle;
 UploadProgress(Activity owner){activity=owner;ui.post(()->{if(closed||activity.isDestroyed()||activity.isFinishing())return;LinearLayout box=new LinearLayout(activity);box.setOrientation(1);int pad=(int)(24*activity.getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);label=new TextView(activity);label.setText("↑ 0%");label.setTextSize(20);label.setGravity(Gravity.CENTER);box.addView(label);bar=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);box.addView(bar,new LinearLayout.LayoutParams(-1,pad));dialog=new AlertDialog.Builder(activity).setView(box).setCancelable(false).create();dialog.show();lifecycle=new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){close();}};activity.getWindow().getDecorView().addOnAttachStateChangeListener(lifecycle);});}
 public void sent(long bytes,long total){ui.post(()->{if(closed||label==null)return;int percent=(int)Math.min(99,bytes*100/Math.max(1,total));label.setText(bytes>=total?"Đang hoàn tất…":"↑ "+percent+"%");bar.setProgress(percent);});}
 void close(){ui.post(()->{closed=true;if(lifecycle!=null)activity.getWindow().getDecorView().removeOnAttachStateChangeListener(lifecycle);if(dialog!=null&&dialog.isShowing())dialog.dismiss();});}
}
